internal object DuaKokDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_praising_someone" to DuaText("कोणाकूय तोखणाय करतना", "हांव अशें आनी अशें मानतां, आनी अल्लाह ताचो मानपी, आनी हांव अल्लाह मुखार कोणाचीय पवित्रताय दाखोवंक ना.", "कोणाकूय तोखणाय करतना, अतिशयोक्ती करपा बदला.", "पैगंबर सल्ल्याह अलियाह वसलमान तोखणाय करपाचें हें शिश्टाचार शिकयलें."),
        "dua_being_praised" to DuaText("जेन्ना तुजी तोखणाय जाता", "हे अल्लाह, ते कितें सांगतात ताचो म्हाका हिशोब दिवचो न्हय, आनी तांकां खबर नाशिल्ल्या गजालीं खातीर म्हाका माफ कर.", "स्वताची तोखणाय आयकून-एक साथीदार (आर. ए.) ची पद्दत.", "तोखणाय केल्यार अहंकार टाळपाचो एक मार्ग."),
        "dua_non_muslim_sneezes" to DuaText("जेन्ना बिगर मुसलमान शिंकता", "अल्लाह तुमकां मार्गदर्शन करचो आनी तुमचे काम सारकें करचें.", "जेन्ना एक बिगर मुसलमान शिंकता आनी'अल्हमदुलिल्लाह \"म्हणटा.", "'यारहामुकल्ला \"म्हणटलो अशी आस्त बाळगून ज्यू पैगंबर सल्ल्याह अल्लीह वसलमा लागीं शिंकतले, आनी तो अशें म्हणटलो."),
        "dua_reply_ahl_kitab_salam" to DuaText("सलाम ऑफ पीपल ऑफ द बुक हाका जाप दिवप", "आनी तुज्याचेर.", "जेन्ना पुस्तकाचे लोक सलाम करून अभिवादन करतात.", "पैगंबर सल्ल्याह अलियाह वसलमाचो उपदेश."),
        "dua_fasting_invited" to DuaText("उपवास करतना केन्ना आपयलो", "हांव उपवास करता.", "उपवास करतना, वा कोणूय तुमच्या कडेन झगडटा तेन्ना आपयतात.", "उपवास करपी मनशान निमंत्रण मान्य केल्यार, ताणें यजमानाक प्रार्थना करची."),
        "dua_for_who_gave_drink" to DuaText("कोण म्हाका पोसयतलो ताचे खातीर", "हे अल्लाह, म्हाका पोसपीक पोस आनी पिवोवपीक पिवय.", "कोणूय तुका अन्न वा पेय दिता.", "पैगंबर सल्ल्याह अलियाह वसलमान अल-मक्दाद (आर. ए.) खातीर ही दुआ केली."),
        "dua_eid_greeting" to DuaText("ईदची नमस्कारी", "अल्लाह आमचे कडल्यान आनी तुज्या कडल्यान (बरे काम) स्वीकारपाक जाय.", "ईद दिसा एकामेकांक-कुलीन साथीदारांची (आर. ए.) प्रथा.", "ईदाक मेळ्ळ्या तेन्ना साथीदारांनी हें सांगलें."),
        "dua_wedding_night" to DuaText("निकाह उपरांत व्हंकले खातीर", "हे अल्लाह, तूं तिका निर्माण केल्ल्या सैमाचें बरें आनी बरें कितें तें हांव तुका मागता, आनी तूं तिका निर्माण केल्ल्या सैमाच्या वायट आनी वायट गजालीं पसून हांव तुका आलाशिरो मागता.", "निकाह जाले उपरांत बायलेच्या कपलाचेर हात दवरात.", "पैगंबरांची सल्ल्याह अलियाह वसलम शिकवण-लग्नांत आशीर्वाद."),
        "dua_istisqa_ibadak" to DuaText("तुमच्या सेवकांक आनी जनावरांक उदक दिवचें.", "हे अल्लाह, तुज्या सेवकांक आनी जनावरांक उदक दिवचें, तुजी दया पसरोवची आनी तुज्या मेल्ल्या जमनीक जिवीत दिवचें.", "पावस मागप (इस्तिस्का).", "पैगंबर सल्ल्याह अलियाह वस्लमान पावसा खातीर ही दुआ केली."),
        "dua_seeing_clouds" to DuaText("काळे ढग पळोवप", "हे अल्लाह, हांव तुका ताच्या वायटपणांतल्यान आलाशिरो मागता.", "मळबांत काळे ढग दिसल्यार; पावस पडल्यार'अल्लाहुम्मा सैय्यबन नफिया \"अशें म्हणात.", "ढग पळोवन पैगंबर सल्ल्याह अलियाह वसलाम तो कितें करतालो तें सोडून दितालो आनी ही दुआ करतालो."),
        "dua_jamarat" to DuaText("जमाराटाचेर दगडफेक", "अल्लाह सगळ्यांत व्हड आसा.", "दर एक कांटो फेकून.", "पैगंबर सल्लल्लाह अलीह वसलमान दर एक कांट्याच्या बरोबर तकबीर म्हणटाले, मागीर पयल्या आनी दुसऱ्या जमरा उपरांत किब्लाक तोंड दिवन एक लांब दुआ केली."),
        "dua_rabbi_ainni" to DuaText("म्हज्या देवा, म्हाका मदत कर, म्हजे आड न्हय", "म्हज्या देवा, म्हाका मदत कर आनी म्हजे आड हेरांक मदत करची ना, म्हाका जैत दिवचें आनी हेरांक म्हज्याचेर जैत दिवचें न्हय, म्हजे खातीर येवजण कर आनी म्हजे आड येवजण करची न्हय, म्हाका मार्गदर्शन कर आनी म्हजे आड मार्गदर्शन करप सोंपें कर, आनी कोण म्हज्या आड अन्याय करता ताचे आड म्हाका मदत कर.", "पैगंबर सल्ल्याह अलियाह वसलमाचो (उक्तावपी भाग) एक व्यापक दुआ.", "धर्म आनी ह्या संवसारांतली सगळी मदत एकठांय करपी दुआ."),
        "dua_ati_nafsi_taqwaha" to DuaText("म्हज्या आत्म्याक ताचो तक्वा दिवचो.", "हे अल्लाह, म्हज्या आत्म्याक ताची धर्मनिष्ठा दिवची आनी ताका शुध्द कर, कारण तें शुध्द करपाक तूं सगळ्यांत बरो. तूं ताचो राखणदार आनी ताचो गुरू.", "स्वताची सुदारणा आनी शुध्दीकरण करपा खातीर.", "पैगंबर सल्ल्याह अलियाह वसलम ही दुआ करताले."),
        "dua_iqsim_lana_khashyatik" to DuaText("तुजे विशीं असो भंय आम्हांक दिव.", "हे अल्लाह, तूं आमच्यांत येवपाक आनी तुजी आज्ञा मोडपाक जाय तितली भंय आमकां दिवची, तुज्या स्वर्गांत हाडपाक जाय तितली आज्ञा पाळची, आनी ह्या संवसारांतल्या संकटांक आमच्यासाठी सोंपें करपा खातीर जाय तितली निश्चिती दिवची. तूं आमकां जिवीत दवरता, आनी तें आमचेर उरता मेरेन आमी आमचे आयकुपाक, आमचे नदरेक आनी आमच्या सामर्थ्याचो आनंद घेवचो. आमचेर अन्याय करपी लोकांचेर सूड घे, आमच्या दुस्मानांचेर आमची मदत कर, आमची संकश्ट आमच्या धर्मांत जावची न्हय, ह्या संवसाराक आमची सगळ्यांत व्हड चिंता वा आमच्या ज्ञानाची मर्यादा करची न्हय, आनी आमचेर दया दाखोवपी लोकांक आमचेर घालची न्हय.", "जमनीतल्यान उठतना-पैगंबर सल्ल्याह अलियाह वसलम ही दुआ केल्या बगर क्वचितच उठलो.", "धर्माच्या, ह्या जगाच्या आनी परतीच्या भल्या खातीर एक व्यापक दुआ."),
        "dua_infani_bima_allamtani" to DuaText("तूं म्हाका जें शिकयल्या ताचो फायदो घे.", "हे अल्लाह, तूं म्हाका जें शिकयलां तें म्हाका फायदो कर, कितें फायदो जातलो तें म्हाका शिकय, आनी म्हाका गिन्यान वाडय.", "गिन्यान सोदतना वा अभ्यास करचे पयलीं.", "फायद्याचे गिन्यान आनी ताचेर कृती करपा खातीर एक दुआ."),
        "dua_jar_su" to DuaText("वायट शेजऱ्या कडल्यान आश्रय", "हे अल्लाह, हांव कायम रावपाच्या सुवातेर एका वायट शेजाऱ्या कडल्यान तुका आलाशिरो मागता, कारण प्रवासाचेर आशिल्लो शेजाळो फुडें वता.", "वायट शेजाऱ्या पसून राखणे खातीर.", "पैगंबर सल्ल्याह अलियाह वसलमान हाचे पसून आलाशिरो घेवपाचो आदेश दिलो."),
        "dua_ishfi_abdak" to DuaText("दुयेंत व्यक्ती बरे जावपा खातीर", "हे अल्लाह, तुज्या सेवकाक बरे कर, जाका लागून तो तुज्या खातीर दुस्मानाक तोंड दिवंक शकता वा तुज्या खातीर प्रार्थना करपाक चलूंक शकता.", "दुयेंत मनशाक भेट दितना ताचे खातीर.", "पैगंबर सल्ल्याह अलियाह वसलमान दुयेंतीं खातीर हें सांगपाक शिकयलें."),
        "dua_la_mania" to DuaText("तूं जें दिता तें कोणूच आडावंक शकना.", "अल्लाह सोडून उपासनेचो कोणाकूच अधिकार ना, फकत अल्लाह, भागीदार नासतना. ताचेंच राज्य आसा आनी ताची तोखणाय आसा, आनी ताका सगळ्या गजालींचेर अधिकार आसा. हे अल्लाह, तूं जें दिता तें कोणूच आडावंक शकना आनी तूं जें आडावता तें कोणूच दिवंक शकना, आनी गिरेस्त लोकांच्या संपत्तीचो तुका विरोध करून कसलोच फायदो जायना.", "सक्तीच्या प्रार्थनेच्या सलमा उपरांत.", "पैगंबर सल्ल्युल्लाह अलियाह वसलमान दर एक सक्तीची प्रार्थना केल्या उपरांत हें सांगलें."),
        "dua_slaughtering" to DuaText("जनावरांची कत्तल करतना", "अल्लाहच्या नांवान, आनी अल्लाह सगळ्यांत व्हड आसा.", "जनावरांचो बळी दितना वा मारतना.", "पैगंबर सल्ल्याह अलियाह वसलमान बलिदानाच्या वेळार बिस्मिल्लाह आनी तकबीर अशें सांगलें."),
        "dua_undressing" to DuaText("कपडे उडोवपा वेळार", "अल्लाहच्या नांवान.", "कपडे उडोवपा वेळार (घसल वा बदलपा खातीर).", "जिनाच्या दोळ्यां मदीं आनी मनशाच्या गुप्तांगां मदीं ती एक पडद्याची रुपांतर जाता."),
        "dua_ilbas_jadidan" to DuaText("कोणाकूय नवे कपडे पळयल्यार", "नवे घालात, तोखणाय करपा सारकें जगात आनी हुतात्म्यान मरतात.", "मुसलमान भावाक नव्या कपड्यांत पळोवन.", "उमर (रा.) हाका नव्या वस्त्रांनी पळोवन पैगंबर सल्ल्याह अलियाह वस्लमान ही दुआ केली."),
        "dua_hajj_la_riya" to DuaText("दाखोवपा पसून मुक्त हज", "हे अल्लाह, (ताका) दाखोवंक नाशिल्लें आनी नामनेची सोद घेवंक नाशिल्लें हज कर.", "हज करपाचो हेतू दवरतना प्रामाणीकपणाक.", "पैगंबर सल्ल्याह अलियाह वसलमान हज वेळार ही दुआ केली."),
        "dua_q_muslimayni_laka" to DuaText("इब्राहिम आनी इस्माईल (ए. एस.) हांचो दुआ-आमकां आज्ञाकारी कर", "म्हज्या प्रभू, तूं आनी आमच्या संततींतलें आमी दोगांयक तुजे आनी तुज्या वंशजांक आदारीत आशिल्लें राष्ट्र कर. आम्हांक आमचे उपासनेचे संस्कार दाखय आनी आमची पश्चात्ताप मान्य कर. खरें म्हणल्यार तूं पश्चात्ताप करपी, दयाळू.", "स्वता खातीर आनी आपल्या वंशजांक शरणागती दाखोवपाची दुआ.", "काबा बांदतना ही दुआ तयार केल्ली."),
        "dua_q_iftah_baynana" to DuaText("शुऐबाचो दुआ (ए. एस.)-आमच्यामध्ये न्यायाधीश", "म्हज्या देवा, आमच्याय आनी आमच्या लोकां मदीं खरेंपणान न्याय कर, आनी तूं सगळ्यांत बरो न्याय करपी.", "सत्य आनी खोट्या हांचे मदलो निर्णय घेवपा खातीर.", "शुऐब (ए. एस.) हाचो दुआ जेन्ना ताच्या लोकांनी ताका न्हयकार दिलो."),
        "dua_q_la_akuna_zahiran" to DuaText("मुसाचो दुआ (ए. एस.)-केन्नाच गुन्यांवकारांचो आदार करपी न्हय", "म्हज्या देवा, तूं म्हजेचेर केल्ल्या कृपाक लागून हांव केन्नाच गुन्यांवकारांक आदार करपी जावचो ना.", "अल्लाहच्या आशीर्वादांखातीर उपकार मानप आनी अपराधीक मदत करची ना अशी प्रतिज्ञा.", "पश्चात्तापा उपरांत मुसा (ए. एस.) हाचें वचन."),
        "dua_q_nuh_unsurni" to DuaText("नूहाचो दुआ (ए. एस.)-म्हाका मदत कर, ते म्हाका न्हयकार दितात", "म्हज्या देवा, म्हाका मदत कर, कारण तांणी म्हाका न्हयकारला.", "जेन्ना लोक तुमकां न्हयकारतात आनी सत्य न्हयकारतात.", "नूह (ए. एस.) हाचें दुआ, जाचें उत्तर दिलें."),
        "dua_q_ihkum_bil_haqq" to DuaText("म्हजो प्रभू, सत्यान न्याय कर", "म्हज्या प्रभू, सत्यान न्याय कर. आनी आमचो प्रभू परम दयाळू आसा, जाची मदत तूं सांगपाखातीर मागता.", "खोट्या आनी खोट्या आरोपांक तोंड दिवप.", "पैगंबर सल्ल्याह अलियाह वसलमाक एक दुआ शिकयलो."),
        "dua_ghalabatid_dayn" to DuaText("क्रशिंग रीण आनी दुस्मानां पसून शरण", "हे अल्लाह, रिणाक लागून भारासतना, दुस्मानाक लागून आनी दुस्मानांच्या गर्जना पसून हांव तुका आलाशिरो मागता.", "रिणाच्या ओडल्यान आनी दुस्मानांच्या वर्चस्वा पसून राखण.", "पैगंबर सल्लल्लाह अल्लीह वसलम ह्या गजालीं पसून आलाशिरो घेतालो."),
        "dua_faqr_qillah_dhillah" to DuaText("गरिबी आनी अपमान हांचे पसून शरण", "हे अल्लाह, गरिबी, उणाव आनी अपमान, आनी हेरांचेर अन्याय करप वा अन्याय जावप हांचे पसून हांव तुका आलाशिरो मागता.", "कश्ट, गरज आनी अपमान हांचे पसून सुरक्षीत रावप.", "पैगंबर सल्ल्याह अलियाह वसलमान शिकयल्लो आलाशिरो."),
        "dua_five_things_new_muslim" to DuaText("माफ कर, दया कर, मार्गदर्शन कर, बरे कर, पुरवण कर", "हे अल्लाह, म्हाका माफ कर, म्हज्याचेर दया कर, म्हाका मार्गदर्शन कर, म्हाका कल्याण दिव आनी म्हजी जतनाय कर.", "पैगंबर सल्लल्लाह अलीह वसलमान नव्या मुसलमानांक प्रार्थने वांगडा ही दुआ शिकयली.", "पैगंबर सल्ल्याह अलियाह वसलमान सांगलेंः हे उतरां तुज्या खातीर हें जग आनी परलोक एकठांय करतात."),
        "dua_ruku_laka_raka_tu" to DuaText("रुकू-तुज्या मुखार हांव नमलो.", "हे अल्लाह, हांव तुका नमळलां, हांव तुमचेर विश्वास दवरलो आनी हांव तुका शरण गेलो. म्हजें आयकुपाक, म्हजी नदर, म्हजें मन, म्हजी हाडां आनी म्हजी शिरां तुज्या मुखार नमळ आसात.", "रुकू (खास करून ऐच्छिक प्रार्थनांत).", "पैगंबर सल्ल्याह अलियाह वसलमान हें रुकू भाशेंत पठिल्लें."),
        "dua_sujood_laka_sajadtu" to DuaText("सुजूदांत-तुज्याखातीर हांवें प्रस्ट्रेटेड केलें", "हे अल्लाह, हांव तुका नमस्कारा केल्या, हांव तुमचेर विश्वास दवरला आनी हांव तुका शरण गेलो. जो निर्माण केलो, ताका आकार दिलो आनी ताची आयकुपाक आनी पळोवपाक तयार केलो ताका म्हजें तोंड नमस्कारा. धन्य आसा अल्लाह, जो सगळ्यांत बरो निर्मातो.", "सुजूदांत (खास करून ऐच्छिक प्रार्थनेंत).", "पैगंबर सल्ल्याह अलियाह वसलमान सुजूद भाशेंत हें पठिल्लें."),
        "dua_ruku_sujood_subhanaka" to DuaText("म्हजो प्रभू, तुका गौरव असो-म्हाका माफ कर.", "म्हुणून तूं, हे अल्लाह, आमचो प्रभू, आनी तोखणाय तुजी. हे अल्लाह, म्हाका माफ कर.", "रुकू आनी सुजूदांत.", "आयशा (रा.): पैगंबर सल्ल्लाह अलियाह वसलमान हें चड करून रुकू आनी सुजूद भाशेंत सांगलें."),
        "dua_q_musa_li_akhi" to DuaText("मुसाचो दुआ (ए. एस.)-म्हाका आनी म्हज्या भावाक माफ कर.", "म्हज्या प्रभू, म्हाका आनी म्हज्या भावाक माफ कर आनी आमकां तुज्या दयाळ्यांत प्रवेश कर, कारण तूं दयाळू लोकां मदीं परम दयाळू आसा.", "स्वता खातीर आनी आपल्या भावाक वा मोग्यांक क्षमा कर.", "हारून (ए. एस.) खातीर मुसा (ए. एस.) हाचें दुआ."),
        "dua_q_ufawwidu_amri" to DuaText("हांव म्हजें प्रकरण अल्लाहाक सोंपयता", "आनी हांव म्हजो वेव्हार अल्लाहाक सोंपयता. खरें म्हणल्यार, अल्लाह आपल्या सेवकांक सगळें पळोवपी आसा.", "जेन्ना लोक तुमकां विरोध करतात आनी ही गजाल अल्लाहाक सोडपाक जाय.", "फारोच्या लोकां कडल्यान आस्तीकांचे उतर; तेन्ना अल्लाहान ताच्या वायट कटूं पसून ताची राखण केली."),
        "dua_q_hawariyyun" to DuaText("शिष्यांचो दुआ-साक्षीदारां वांगडा आमची नोंद कर", "म्हज्या प्रभू, तूं प्रकट केल्याचेर आमी विस्वास दवरला आनी आमी पैगंबराक अनुसरला, देखून आमची साक्षीदारां मदीं नोंद कर.", "विश्वासांत आनी संदेशवाहकाक अनुसरपाक निश्चीत रावपा खातीर.", "इसाच्या शिष्यांचो दुआ (ए. एस.)."),
        "dua_q_la_tukhzini" to DuaText("इब्राहिम (अ. स.)-म्हजो अपमान करचो न्हय", "आनी ज्या दिसा तांकां परतून उठयतात त्या दिसा म्हाका बदनाम करचो न्हय.", "पुनरुत्थान दिसा अपमानासावन सुरक्षीत रावपाक.", "इब्राहिम (अ. स.) हाचें दुआ परका खातीर."),
        "dua_iftar_laka_sumtu" to DuaText("इफ्तार-तुज्या खातीर हांवें फेस्ट केल्लें", "हे अल्लाह, हांवें तुज्या खातीर उपास केला आनी तुज्या अन्नदानान हांव म्हजो उपवास मोडता.", "उपवास मोडतना (नामनेचो इफ्तार दुआ).", "पैगंबर सल्लल्लाह अलीह वस्लमान इफ्तारांत हें सांगलें. हेर आख्यायिकांनी बळकट केल्लें हें एक मुर्सल कथन; इफ्ताराक ताचो पठण करप ही हनाफींची आनी भोवसंख्यांची पद्दत."),
        "dua_iftar_ibn_umar" to DuaText("इफ्तार-तुज्या व्हड दयाळ्यान, म्हाका माफ कर.", "हे अल्लाह, हांव तुका सगळ्या गजालींचो आस्पाव आशिल्ल्या तुझ्या दये वरवीं म्हाका माफ करची अशी विनवणी करता.", "इफ्तारा वेळार-अब्दुल्ला इब्न अम्र (रा.) हाणें ही दुआ केली; इफ्तारा वेळार उपास करपी मनशाची दुआ न्हयकारना.", "हदीस-इफ्ताराच्या वेळार उपवास करपी मनशाची दुआ न्हयकारना."),
        "dua_inni_saim" to DuaText("उपवास करतना राग येता तेन्ना", "हांव उपवास करता, हांव उपवास करता.", "जेन्ना उपवास करतना कोणूय तुमचो अपमान करता वा तुमचो झगडटा.", "पैगंबर सल्लल्लाह अलियाह वसलमान सांगलेंः उपवास करप ही एक ढाल, देखून उपवास करपी मनशान अश्लील उलोवंक जायना वा अज्ञानीपणान वागूंक जायना-कोणूय झगडत जाल्यार हें दोन फावटीं सांग."),
    )
}
